mapper.select:
select coalesce((select case when c.expires_at < now() then '{"err":"expired"}' else json_build_object('session_id', c.session_id, 'expires_at', lms_ts(c.expires_at), 'rotate_sec', c.rotate_sec,
      'qr', 'DDATT1.' || c.session_id || '.' || k.slot || '.' || substr(encode(sha256(convert_to(c.qr_secret || '|' || k.slot, 'UTF8')), 'hex'), 1, 12), 'next_at', lms_ts(to_timestamp((k.slot + 1) * c.rotate_sec)))::text end
    from lms_attendance_code c, lateral (select floor(extract(epoch from now()) / c.rotate_sec)::bigint slot) k where c.session_id = cast(#{session_id,jdbcType=VARCHAR} as uuid)), '{"err":"no_code"}')
